// Endpoint Permission: Admin, Non-Signing Admin, Signer, Approver.
func (s *VaultsService) SetUsdcGatewayDepositAutomationBeta(ctx context.Context, vaultAccountID string, body *AutomationSettingsRequest, opts ...RequestOption) (*SaveAutomationSettingsResponse, error) {
	r := newRequest(http.MethodPost, "/vault/accounts/{vaultAccountId}/virtual_asset_wallet/usdc_gateway/deposit_automation")
	r.path = "/vault/accounts/" + r.pathParam("vaultAccountId", vaultAccountID) + "/virtual_asset_wallet/usdc_gateway/deposit_automation"
	if body != nil {
		r.body = body
	}
	var out SaveAutomationSettingsResponse
	if err := s.core.do(ctx, r, &out, opts); err != nil {
		return nil, err
	}
	return &out, nil
}

// DisableUsdcGatewayDepositAutomationScheduleBeta calls DELETE /vault/accounts/{vaultAccountId}/virtual_asset_wallet/usdc_gateway/deposit_automation/{automationId}.
